/// <reference types="@stdlib/types"/>

import { ndarray } from '@stdlib/types/ndarray';
import everyBy = require( '@stdlib/ndarray/base/every-by' );
import unaryReduceSubarrayBy = require( './index' );


const x: ndarray = {
	'byteLength': null,
	'BYTES_PER_ELEMENT': null,
	'data': [ 1, 2, 3, 4 ],
	'dtype': 'generic',
	'flags': {
		'ROW_MAJOR_CONTIGUOUS': true,
		'COLUMN_MAJOR_CONTIGUOUS': false
	},
	'length': 4,
	'ndims': 2,
	'offset': 0,
	'order': 'row-major',
	'shape': [ 2, 2 ],
	'strides': [ 2, 1 ],
	'get': function get( i ) {
		return this.data[ i ];
	},
	'set': function set( i, v ) {
		this.data[ i ] = v;
		return this;
	}
};

const y: ndarray = {
	'byteLength': null,
	'BYTES_PER_ELEMENT': null,
	'data': [ 0.0, 0.0 ],
	'dtype': 'generic',
	'flags': {
		'ROW_MAJOR_CONTIGUOUS': true,
		'COLUMN_MAJOR_CONTIGUOUS': false
	},
	'length': 2,
	'ndims': 1,
	'offset': 0,
	'order': 'row-major',
	'shape': [ 2 ],
	'strides': [ 1 ],
	'get': function get( i ) {
		return this.data[ i ];
	},
	'set': function set( i, v ) {
		this.data[ i ] = v;
		return this;
	}
};

/**
* Callback function.
*
* @param v - ndarray element
* @returns result
*/
function clbk( v: number ): boolean {
	return v > 0.0;
}


// TESTS //

// The function returns 'undefined'...
{
	var arrays = [ x, y ];
	var dims = [ 1 ];
	unaryReduceSubarrayBy( everyBy, arrays, dims, clbk ); // $ExpectType void
	unaryReduceSubarrayBy( everyBy, arrays, dims, clbk, {} ); // $ExpectType void
	unaryReduceSubarrayBy( everyBy, arrays, dims, {}, clbk ); // $ExpectType void
	unaryReduceSubarrayBy( everyBy, arrays, dims, {}, clbk, {} ); // $ExpectType void
}

// The compiler throws an error if the function is provided a first argument which is not a function...
{
	var arrays = [ x, y ];
	var dims = [ 1 ];
	unaryReduceSubarrayBy( 5, arrays, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( true, arrays, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( false, arrays, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( null, arrays, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( undefined, arrays, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( {}, arrays, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( [1], arrays, dims, clbk ); // $ExpectError

	unaryReduceSubarrayBy( 5, arrays, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( true, arrays, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( false, arrays, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( null, arrays, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( undefined, arrays, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( {}, arrays, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( [1], arrays, dims, clbk, {} ); // $ExpectError

	unaryReduceSubarrayBy( 5, arrays, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( true, arrays, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( false, arrays, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( null, arrays, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( undefined, arrays, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( {}, arrays, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( [1], arrays, dims, {}, clbk ); // $ExpectError

	unaryReduceSubarrayBy( 5, arrays, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( true, arrays, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( false, arrays, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( null, arrays, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( undefined, arrays, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( {}, arrays, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( [1], arrays, dims, {}, clbk, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an array-like object containing ndarray-like objects...
{
	var dims = [ 1 ];
	unaryReduceSubarrayBy( everyBy, 5, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, true, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, false, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, null, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, undefined, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, {}, dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, [1], dims, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, ( x: number ): number => x, dims, clbk ); // $ExpectError

	unaryReduceSubarrayBy( everyBy, 5, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, true, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, false, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, null, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, undefined, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, {}, dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, [1], dims, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, ( x: number ): number => x, dims, clbk, {} ); // $ExpectError

	unaryReduceSubarrayBy( everyBy, 5, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, true, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, false, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, null, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, undefined, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, {}, dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, [1], dims, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, ( x: number ): number => x, dims, {}, clbk ); // $ExpectError

	unaryReduceSubarrayBy( everyBy, 5, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, true, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, false, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, null, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, undefined, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, {}, dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, [1], dims, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, ( x: number ): number => x, dims, {}, clbk, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not an array of integers...
{
	var arrays = [ x, y ];

	unaryReduceSubarrayBy( everyBy, arrays, 5, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, true, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, false, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, null, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, undefined, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, ( x: number ): number => x, clbk ); // $ExpectError

	unaryReduceSubarrayBy( everyBy, arrays, 5, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, true, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, false, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, null, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, undefined, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, ( x: number ): number => x, clbk, {} ); // $ExpectError

	unaryReduceSubarrayBy( everyBy, arrays, 5, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, true, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, false, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, null, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, undefined, {}, clbk ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, ( x: number ): number => x, {}, clbk ); // $ExpectError

	unaryReduceSubarrayBy( everyBy, arrays, 5, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, true, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, false, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, null, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, undefined, {}, clbk, {} ); // $ExpectError
	unaryReduceSubarrayBy( everyBy, arrays, ( x: number ): number => x, {}, clbk, {} ); // $ExpectError
}


// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const arrays = [ x, y ];
	const dims = [ 1 ];

	unaryReduceSubarrayBy(); // $ExpectError
	unaryReduceSubarrayBy( arrays ); // $ExpectError
	unaryReduceSubarrayBy( arrays, clbk, dims ); // $ExpectError
	unaryReduceSubarrayBy( arrays, clbk, dims, {}, clbk, {}, true ); // $ExpectError
}
